// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // 1. Initialize the contract to a valid state
        vm.assume(recipient != address(0));
        c.init(address(this), address(this), address(this));

        // 2. Record the internal state before and after to derive the actual count
        //    The reference should always have proposalCount == number of calls
        uint256 calls = 5;
        uint256[] memory ids = new uint256[](calls);

        for (uint256 i = 0; i < calls; i++) {
            c.newGrantProposal(recipient, amount);
            ids[i] = i + 1; // expected proposal IDs if count increments before emit
        }

        // 3. Read the published state after all calls
        uint256 finalCount = c.proposalCount();

        // 4. Verify that the final count equals the number of calls
        //    The reference satisfies this for ALL inputs, but the buggy version fails for the first call
        assertEq(finalCount, calls, "proposalCount must match number of successful newGrantProposal calls");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // 1. Widen domain: recipient non-zero, amount non-zero to avoid trivial edge cases
        vm.assume(recipient != address(0));
        vm.assume(amount > 0);
        // initialize c with mock addresses to satisfy init() only once
        c.init(address(0x1), address(0x2), address(0x3));
        // 2. Drive c through newGrantProposal
        vm.prank(address(this));
        c.newGrantProposal(recipient, amount);
        // 3. Assert: the newly stored grant is under proposalCount (which has been incremented in reference, but mutant stores under old count)
        // In reference, mapPID_grant[proposalCount] holds recipient; in mutant, mapPID_grant[proposalCount-1] holds it and mapPID_grant[proposalCount] is zero.
        (address storedRecipient, uint256 storedAmount) = c.mapPID_grant(c.proposalCount());
        assertTrue(storedRecipient == recipient && storedAmount == amount);
    }
}

