// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // The bug manifests only when coolOffPeriod affects the time check in finaliseProposal.
        // We need to create a valid grant proposal with at least minority/quorum, initiate finalisation,
        // and then call finaliseProposal within the same block. The reference rejects it; the bug accepts it.

        // Bound amount to be positive and small enough for the grant check (<10% of VAULT's USDV balance)
        vm.assume(amount > 0 && amount < type(uint256).max / 10);
        vm.assume(recipient != address(0));

        // Deploy a minimal VAULT mock that returns a non-zero totalWeight and USDV balance
        // to satisfy hasQuorum, hasMinority, and the 10% balance check.
        VaultMock vault = new VaultMock();
        UsdvMock usdv = new UsdvMock();
        VaderMock vader = new VaderMock();

        // Initialize the contract with mocked addresses
        c.init(address(vader), address(usdv), address(vault));

        // Set up VAULT to have enough totalWeight so that a single voter meets minority (> totalWeight/6)
        // and quorum (> totalWeight/3). We also need USDV balance in VAULT high enough for the grant.
        // For simplicity, set totalWeight = 12 and USDV balance = 10 * amount + 1.
        vault.setTotalWeight(12);
        usdv.setBalance(address(vault), 10 * amount + 1);

        // We'll be the only voter, so we need our weight to be > 12/6=2 for minority,
        // and > 12/3=4 for quorum. We set our weight to 5.
        address voter = address(0xBEEF);
        vault.setMemberWeight(voter, 5);

        // Create a new grant proposal
        vm.prank(voter);
        c.newGrantProposal(recipient, amount);
        uint256 pid = c.proposalCount();

        // Vote on the proposal to start finalising
        vm.prank(voter);
        c.voteProposal(pid);

        // At this point, finalising should be true, and mapPID_timeStart should be block.timestamp.
        // With coolOffPeriod = 0 (bug), finaliseProposal will succeed immediately.
        // With coolOffPeriod = 1 (reference), it will fail because block.timestamp - timeStart == 0 <= 1.
        bool success;
        try c.finaliseProposal(pid) {
            success = true;
        } catch {
            success = false;
        }

        // The property: if a proposal was just finalised (same block), finaliseProposal must never succeed
        // because the cool-off period has not elapsed. The reference always reverts; the mutant succeeds.
        assertTrue(!success);
    }
}

// Minimal mock Vault that lets us control totalWeight and memberWeight.
contract VaultMock {
    uint256 private _totalWeight;
    mapping(address => uint256) private _memberWeight;

    function setTotalWeight(uint256 w) external { _totalWeight = w; }
    function setMemberWeight(address member, uint256 w) external { _memberWeight[member] = w; }
    function totalWeight() external view returns (uint256) { return _totalWeight; }
    function getMemberWeight(address member) external view returns (uint256) { return _memberWeight[member]; }
    function grant(address, uint256) external {}
}

// Minimal mock USDV token that lets us set balanceOf for the vault
contract UsdvMock {
    mapping(address => uint256) private _balances;
    function setBalance(address account, uint256 bal) external { _balances[account] = bal; }
    function balanceOf(address account) external view returns (uint256) { return _balances[account]; }
}

// Minimal mock VADER that does nothing
contract VaderMock {
    function changeUTILS(address) external {}
    function setRewardAddress(address) external {}
}

