// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address proposedAddr, string calldata typeStr) public {
        vm.assume(proposedAddr != address(0));
        vm.assume(bytes(typeStr).length > 0);

        // 1. init C with dummy addresses for external deps; we don't need real ones for this property
        c.init(address(this), address(this), address(this));

        // 2. drive c through newAddressProposal
        c.newAddressProposal(proposedAddr, typeStr);

        // 3. general rule: after a call to newAddressProposal, the latest proposal ID
        // must have a stored address equal to the argument. The bug skips IDs, so
        // mapPID_address[proposalCount] will be zero address while mapPID_address[proposalCount-1]
        // holds the argument (or vice versa depending on read). We assert that the address
        // stored at the current proposalCount equals the passed argument.
        uint256 pid = c.proposalCount();
        assertEq(c.mapPID_address(pid), proposedAddr, "stored address mismatch at latest PID");
    }
}

