// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address vader, address usdv, address vault, address recipient, uint256 amount, address actor) public {
        vm.assume(vader != address(0) && usdv != address(0) && vault != address(0));
        vm.assume(recipient != address(0));
        vm.assume(amount > 0);

        c.init(vader, usdv, vault);
        // Create two proposals of the same type
        vm.prank(actor);
        c.newGrantProposal(recipient, amount);
        uint256 oldID = 1;
        vm.prank(actor);
        c.newGrantProposal(recipient, amount);
        uint256 newID = 2;

        // Vote on old proposal to give it some weight
        vm.prank(actor);
        c.voteProposal(oldID);

        // Move old proposal into finalising state (requires meeting quorum; we'll need to manipulate totalWeight via vault to be 0 so any vote works)
        // Make totalWeight 0 so any non-zero votes pass quorum and majority -> auto finalise
        vm.prank(actor);
        c.voteProposal(oldID); // second vote from same actor would reduce but we will just rely on totalWeight being 0 by default mock
        // Actually, VAULT interface calls are external and unreachable here without mock; totalWeight returns 0 by default from foundry mock call, so hasQuorum(0>0?) no.
        // We'll use vm.mockCall? No, we cannot. We'll just accept that we cannot trigger finalising in a pure fuzz without mocking, but the cancel requires finalising.
        // So we need a way to set mapPID_finalising to true. The only way is via _finalise which is internal and called from voteProposal if quorum met.
        // Since we cannot mock iVAULT calls, totalWeight returns 0, hasQuorum will be false for any positive vote count. So we cannot easily make it finalise.
        // However, the property we want to check is mapPID_votes[oldID] after cancelProposal, regardless of finalising; but cancelProposal requires finalising == true.
        // Without mocking, we cannot satisfy that require. We need adversarial helper to supply a VAULT that returns non-zero totalWeight so quorum can be reached.
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oldId, uint256 newId, address recipient, uint256 amount, address actor1, address actor2) public {
        vm.assume(oldId != newId);
        vm.assume(oldId > 0 && newId > 0);
        vm.assume(amount > 0);
        vm.assume(actor1 != address(0) && actor2 != address(0));
        vm.assume(actor1 != actor2);
        vm.assume(recipient != address(0));

        // Deploy a mock VADER that does nothing on changeUTILS/setRewardAddress
        MockVADER vader = new MockVADER();
        // Deploy a mock USDV that returns a huge balance to avoid grant constraint
        MockUSDV usdv = new MockUSDV();
        // Deploy a mock VAULT that allows us to control weights
        MockVAULT vault = new MockVAULT();

        c.init(address(vader), address(usdv), address(vault));

        // Create two proposals of same type so cancelProposal can be called
        vm.prank(actor1);
        c.newAddressProposal(actor1, "UTILS");
        vm.prank(actor2);
        c.newAddressProposal(actor2, "UTILS");

        // Give actor1 and actor2 weight in VAULT
        vault.setWeight(actor1, 100);
        vault.setWeight(actor2, 100);
        vault.setTotalWeight(200);

        // Set USDV balance to large so grant limit not hit
        usdv.setBalance(address(vault), type(uint256).max);

        // Both vote to make first proposal finalising (quorum > totalWeight/3)
        vm.prank(actor1);
        c.voteProposal(oldId);
        vm.prank(actor2);
        c.voteProposal(oldId);

        // Ensure majority for UTILS type so _finalise triggered
        // With 200 votes for oldId, totalWeight=200 => quorum 66, majority 100 -> satisfied
        // Now cancel with newId which has minority (newId votes = 0)
        vm.prank(actor1);
        c.cancelProposal(oldId, newId);

        // assert: after cancelProposal, the old proposal's finalising flag must be false in the reference contract
        // The mutant fails to reset it, so it remains true
        // Access mapPID_finalising via auto-generated public getter
        bool finalising = c.mapPID_finalising(oldId);
        assertTrue(!finalising);
    }
}

contract MockVADER {
    function changeUTILS(address) external { }
    function setRewardAddress(address) external { }
    function DAO() external pure returns (address) { return address(0); }
    function UTILS() external pure returns (address) { return address(0); }
    function emitting() external pure returns (bool) { return false; }
    function minting() external pure returns (bool) { return false; }
    function secondsPerEra() external pure returns (uint) { return 1; }
    function flipEmissions() external { }
    function flipMinting() external { }
    function changeDAO(address) external { }
    function purgeDAO() external { }
    function upgrade(uint) external { }
    function redeem() external pure returns (uint) { return 0; }
    function redeemToMember(address) external pure returns (uint) { return 0; }
}

contract MockUSDV {
    mapping(address => uint) public balanceOf;
    function setBalance(address a, uint b) external { balanceOf[a] = b; }
