        // Set up VAULT with totalWeight > 0 and balances so quorum/minority/majority work
        vau.setTotalWeight(voteWeight * 6); // ensures consensus values are > 0
        usdv.setBalance(address(vau), voteWeight * 20); // funds for grant

        c.init(address(vad), address(usdv), address(vau));

        // Create two proposals of same type (GRANT) for canceller
        vm.prank(canceller);
        c.newGrantProposal(grantRecipient, 1);
