        vm.prank(canceller);
        c.newGrantProposal(grantRecipient, 1);
        uint newPID = c.proposalCount();

        // Vote on old proposal to give it quorum and start finalising
        vau.setMemberWeight(voter1, voteWeight);
        vm.prank(voter1);
        c.voteProposal(oldPID);

        // We need the old proposal to be finalising, and the new proposal to have minority
        // The mock VAULT's totalWeight is 6*voteWeight.
