        // totalWeight is the VAULT's total weight, allow 0 to catch the edge case
        totalWeight = bound(totalWeight, 0, type(uint256).max / 2);

        // Setup the mock VAULT with the provided total weight
        MockVAULT v = MockVAULT(c.VAULT());
        v.setTotalWeight(totalWeight);

        // Prepare two proposals of the same type to satisfy cancelProposal requirements
        // Both will be "GRANT" type.
        // Use an arbitrary address for grant recipient
        address recipient = address(uint160(uint(keccak256(abi.encode(oldId, newId)))));

        // Create the old proposal (we need its ID to be oldId)
        // The proposalCount starts at 0, so we advance it by creating dummy proposals or setting directly
        // Since we cannot directly set proposalCount, we create (oldId-1) proposals first
        for(uint i = 0; i < oldId - 1; i++) {
            c.newGrantProposal(address(0), 0);
        }
        c.newGrantProposal(recipient, 100); // This is oldId

        // Now create (newId - oldId - 1) proposals to reach newId
        for(uint i = 0; i < newId - oldId - 1; i++) {
            c.newGrantProposal(address(0), 0);
        }
        c.newGrantProposal(recipient, 200); // This is newId

        // Set the old proposal as finalising
        vm.startPrank(address(this));
        // To set finalising, we need to trigger its internal logic which requires quorum.
        // We can directly manipulate the mapPID_finalising storage? No, vm.store is not allowed.
        // Instead, we need to go through the normal flow to get a proposal finalising.
        // The voteProposal function calls _finalise if quorum and (if not DAO/UTILS/REWARD) always.
        // GRANT is not DAO/UTILS/REWARD, so if quorum is reached, _finalise is called.
        // Quorum is totalWeight/3 votes > consensus.
        // First, give this address some weight in the mock VAULT.
        // The mock VAULT needs to return a positive weight for this address.
        // We'll use the mock's setMemberWeight function.
        v.setMemberWeight(address(this), totalWeight / 3 + 1); // Ensure quorum for oldId

        // Vote on oldId to trigger finalise
        c.voteProposal(oldId);
        // Now oldId should be finalising

        // Vote on newId such that it has minority (votes > totalWeight/6)
        v.setMemberWeight(address(this), totalWeight / 6 + 1);
        c.voteProposal(newId);
        vm.stopPrank();

        // Now call cancelProposal
        vm.prank(address(this));
        c.cancelProposal(oldId, newId);

        // After cancelProposal, the old proposal's votes should be less than totalWeight
        // Since it was set to 0 in the reference, but 1 in the mutant, if totalWeight is 0, 1 < 0 is false.
        // However, totalWeight could be 0, and the reference sets to 0 (0 < 0? false) but the mutant sets to 1 (1 < 0? false).
        // Wait, we need a true difference. 
        // Let's reconsider: after cancelProposal, the oldId votes are reset to 0. 
        // The property: the votes of the old proposal must be less than the total votes of the new proposal OR must be 0.
        // Alternative: the sum of votes of old proposal and new proposal must equal the new proposal's votes (since old is zeroed).
        // But in the mutant, it's new + 1.
        // Let's assert: mapPID_votes[oldId] < mapPID_votes[newId] 
        // Because old should be 0, new should be totalWeight/6+1 (which is >0 if totalWeight>=0).
        // For totalWeight=0, newId votes = 0/6+1 = 1, old = 0 (ref) vs 1 (mut), 0 < 1 true, 1 < 1 false.
        // So the assertion mapPID_votes[oldId] < mapPID_votes[newId] catches the case totalWeight=0.
        uint256 oldVotes = c.mapPID_votes(oldId);
        uint256 newVotes = c.mapPID_votes(newId);
        assertTrue(oldVotes < newVotes);
    }
}

