    function testFuzz_property(uint256 oldProposalID, uint256 newProposalID, uint256 totalWeight) public {
        // Bound proposal IDs to reasonable range
        vm.assume(oldProposalID > 0 && oldProposalID <= 1000);
        vm.assume(newProposalID > 0 && newProposalID <= 1000);
        vm.assume(newProposalID != oldProposalID);
        // Bound totalWeight to avoid overflow in hasMinority calculation (totalWeight / 6)
        vm.assume(totalWeight >= 0 && totalWeight <= type(uint256).max / 6);

        // Deploy a minimal VAULT-like helper that returns a fuzzed totalWeight
        VaultMock vault = new VaultMock(totalWeight);

        // Deploy a UTILS-like helper that VADER expects
        UtilsMock utils = new UtilsMock();

        // Deploy a minimal VADER-like helper
        VaderMock vader = new VaderMock(address(utils));

        // Deploy a minimal USDV token for balance checks
        UsdvMock usdv = new UsdvMock();

        // Initialize C with mock addresses
        c.init(address(vader), address(usdv), address(vault));

        // Register proposals with the same type so cancelProposal passes the isEqual check
        // We need mapPID_type[oldProposalID] and mapPID_type[newProposalID] both set
        // We'll use 'UTILS' type; moveUtils requires a non-zero address
        // We'll create proposals via newAddressProposal
        vm.prank(msg.sender);
        c.newAddressProposal(address(0x1), "UTILS");
        vm.prank(msg.sender);
        c.newAddressProposal(address(0x2), "UTILS");

        // Old proposal must be in finalising state
        // We need mapPID_finalising[oldProposalID] == true
        // Finalising is set by _finalise which is called from voteProposal when quorum is reached
        // We'll set totalWeight so that a single vote reaches quorum
        // hasQuorum requires votes > totalWeight / 3
        // With totalWeight, a vote weight of totalWeight exceeds totalWeight/3
        // getMemberWeight will return totalWeight from our vault mock
        // We vote on oldProposalID to trigger finalising
        vm.prank(msg.sender);
        c.voteProposal(oldProposalID);

        // Ensure old proposal is finalising and new proposal has minority
        // hasMinority requires votes > totalWeight / 6
        // newProposalID has 0 votes, need to ensure 0 > totalWeight/6, which is false for totalWeight>0
        // We need minority to be true; requires votes > totalWeight/6
        // We can vote once on newProposalID with weight totalWeight to gain minority
        vm.prank(msg.sender);
        c.voteProposal(newProposalID);

        // Now cancel oldProposalID in favor of newProposalID
        vm.prank(msg.sender);
        c.cancelProposal(oldProposalID, newProposalID);

        // After cancel, old proposal's vote count must be <= minority threshold
        // hasMinority is votes > totalWeight / 6
        // post-condition: NOT hasMinority(oldProposalID) i.e. votes <= totalWeight / 6
        // Bug sets votes to 1; for totalWeight < 6, 1 > totalWeight/6, making hasMinority true
        // Reference sets to 0; 0 <= totalWeight/6 always
        bool minorityAfter = c.hasMinority(oldProposalID);
        assertTrue(!minorityAfter);
    }
}

