        MockERC20 usdv = new MockERC20();

        // 4. Initialize C with our mocks
        c.init(address(vader), address(usdv), address(vault));

        // 5. Create two proposals of the same type (e.g., 'GRANT') to satisfy cancelProposal requirements
        vm.prank(msg.sender);
        c.newGrantProposal(address(0x1), 100); // oldProposalID = 1
        vm.prank(msg.sender);
        c.newGrantProposal(address(0x2), 200); // newProposalID = 2

        // If the fuzzed IDs are not 1 and 2, we need to create them up to the max
        uint256 maxID = oldProposalID > newProposalID ? oldProposalID : newProposalID;
        for (uint256 i = 3; i <= maxID; i++) {
            vm.prank(msg.sender);
            c.newGrantProposal(address(uint160(i)), uint256(i) * 100);
        }

        // 6. Vote on the proposals to give them some weight
        vault.setMemberWeight(address(this), memberWeight);
        vm.prank(address(this));
        c.voteProposal(oldProposalID);
        vm.prank(address(this));
        c.voteProposal(newProposalID);

        // 7. Set totalWeight so that oldProposalID has quorum (to become finalising) and newProposalID has minority
        // hasQuorum: votes > totalWeight / 3
        // hasMinority: votes > totalWeight / 6
        // We need: memberWeight > totalWeight / 3  (so oldProposalID has quorum and becomes finalising)
        // And: memberWeight <= totalWeight / 6  (so newProposalID has minority - wait, minority is > totalWeight/6)
        // Actually, minority is > totalWeight/6, so we need memberWeight > totalWeight/6 but <= totalWeight/3
        // Let's adjust: we need oldProposalID to become finalising, so it needs quorum: memberWeight > totalWeight/3
        // Then newProposalID also needs minority: memberWeight > totalWeight/6 (which is automatically satisfied if > totalWeight/3)
        // So we need: memberWeight > totalWeight/3
        // Also newProposalID must not have quorum, i.e., memberWeight <= totalWeight/3
        // This is contradictory. We need different weights for different proposals.
        // We can vote on oldProposalID with a high weight, and on newProposalID with a low weight.
        // Let's use two different addresses.
        address voter1 = address(0x100);
        address voter2 = address(0x200);

        // Give voter1 high weight to push oldProposalID to quorum
        vault.setMemberWeight(voter1, (totalWeight / 3) + 1);
        vm.prank(voter1);
        c.voteProposal(oldProposalID);

        // Give voter2 low weight so newProposalID has minority but not quorum
        vault.setMemberWeight(voter2, (totalWeight / 6) + 1);
        vm.prank(voter2);
        c.voteProposal(newProposalID);

        // Now oldProposalID should be finalising (assuming hasMajority is false to avoid immediate finalise)
        // We can set totalWeight high enough so that votes < totalWeight/2 (no majority)

        // 8. Execute cancelProposal
        vm.prank(msg.sender);
        c.cancelProposal(oldProposalID, newProposalID);

        // 9. Assert: After successful cancelProposal, old proposal votes must be exactly 0
        assertEq(c.mapPID_votes(oldProposalID), 0, "Old proposal votes must be zero after cancel");
    }
}

