        // For a minimal reproduction: we need a proposal that is not DAO/UTILS/REWARD.
        // The test creates a grant proposal, simulates a vote that pushes it over quorum, and observes finalising.

        // Create a GRANT proposal; its ID will be 1 if no other proposals.
        // Since we can't control the internal counter, we fuzz the recipient and amount.
        address recipient = address(0x1234);
        uint256 amount = 1;
        c.newGrantProposal(recipient, amount);
        uint256 pid = 1; // first proposal

        // The contract relies on VAULT for totalWeight() and getMemberWeight().
        // Without a real VAULT, totalWeight() returns 0, making quorum unreachable.
        // We deploy a helper VAULT that returns a fixed totalWeight > 0 and gives the voter a weight that trips quorum.

        VaultHelper helper = new VaultHelper();
        // Replace the zero address vault with the helper. We cannot call changeVAULT because there is no such function.
        // However, the test can override the address by cheating: vm.store to set the VAULT slot.
        // But the rules forbid vm.store. Instead we deploy C with a pre-set vault? No.
        // The setup deploys C and calls init with zero addresses, which sets VAULT to address(0).
        // We can deploy a fake vault and make the zero address behave like it by using a fallback? Impossible.
        // The only way without vm.store is to deploy C in setUp with a real address? But we must use `new C()`.
        // The init sets the vault; we can redeploy C after setUp? No, setUp runs once.
        // Workaround: we can create a new C instance inside the test and init with the helper's address. That's allowed.
        C c2 = new C();
        c2.init(address(0), address(0), address(helper));
        c2.newGrantProposal(recipient, amount);
        uint256 pid2 = 1;

        // voter votes, which triggers countMemberVotes and then checks quorum/finalising.
        // The helper returns totalWeight = 300 and voter weight = 101, making quorum (votes > 100) true.
        vm.prank(voter);
        bool okRef;
        try c2.voteProposal(pid2) {
            okRef = true;
        } catch {
            okRef = false;
        }

        // After voting, check if the proposal is finalising.
        // The reference should have set mapPID_finalising[pid2] = true;
        // The buggy version doesn't for non-DAO types, so finalising remains false.
        bool finalising = c2.mapPID_finalising(pid2);

        assertTrue(finalising == true);
    }
}

contract VaultHelper {
    function totalWeight() external pure returns (uint256) {
        return 300;
    }

    function getMemberWeight(address) external pure returns (uint256) {
        return 101;
    }
}

