// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        // Initialize with mock addresses where VAULT is a simple mock to return nonzero totalWeight
        address vault = address(new MockVault());
        c.init(address(this), address(this), vault);
    }

    function testFuzz_property(uint256 fuzz_oldVotes, uint256 fuzz_newVotes, uint256 fuzz_actor) public {
        // Bound votes to reasonable range to avoid arithmetic overflow
        fuzz_oldVotes = bound(fuzz_oldVotes, 0, type(uint128).max);
        fuzz_newVotes = bound(fuzz_newVotes, 1, type(uint128).max); // new proposal always has some votes
        address actor = address(uint160(fuzz_actor));

        // Setup: create two proposals of same type (e.g., "DAO")
        vm.prank(actor);
        c.newAddressProposal(address(0x1), "DAO"); // old proposal ID = 1
        vm.prank(actor);
        c.newAddressProposal(address(0x2), "DAO"); // new proposal ID = 2

        // Manually set votes for old and new proposals to fuzzed values using vote weight from mock
        // We simulate votes by pranked calls to voteProposal which sets mapPIDMember_votes and mapPID_votes
        // But since VAULT.totalWeight() is constant (2), we need to manipulate votes directly via internal state?
        // Actually, we can just call voteProposal repeatedly from different actors to accumulate votes
        // However, to set arbitrary fuzzed votes, we override storage directly using vm.store (REJECTED)
        // Instead, we simulate the scenario where the old proposal is finalising and has the specified votes,
        // and the new proposal has the specified votes. We can achieve this by calling voteProposal from many
        // different addresses pre-funded with weight. Since MockVault returns weight 1 per member,
        // we can use many pranks to set votes.

        // Alternative: The bug is triggered when hasMinority is not checked. The property is:
        // "After cancelProposal, mapPID_votes[oldProposalID] becomes 0 ONLY IF hasMinority(newProposalID) is true."
        // But in the buggy version, it always becomes 0 regardless. So we need to test that the revert condition is missing.
        // We can't directly read revert because cancelProposal doesn't revert on successful call in either version.
        // The difference is in state changes: In P, cancelProposal reverts when hasMinority is false, so state remains unchanged.
        // In M, cancelProposal succeeds and changes state (sets old votes to 0) even when hasMinority is false.
        // So the property is: After a call to cancelProposal, if mapPID_votes[oldProposalID] changed to 0,
        // then hasMinority(newProposalID) must have been true before the call.
        // We can test this by checking the revert boolean of cancelProposal call vs the state change.
        // However, the specification says: "the value of state variable `cancelProposal` differs"?? That seems like a typo; 
        // it means the outcome of the cancelProposal function call differs (revert vs success).
        // So we assert: "A cancelProposal call reverts iff hasMinority(newProposalID) is false."

        // To set up votes without vm.store, we use the internal mechanism: voteProposal adds weight to a proposal.
        // We can call voteProposal from many different addresses to accumulate votes.
        // Since we only care about the condition, we can set newProposal votes to be below minority threshold
        // by ensuring totalWeight is high and newVotes low. But we want fuzzer to explore.

        // We'll manually set totalWeight via MockVault to 1000 (fixed).
        // Then minority threshold = 1000/6 = 166. So if newVotes <= 166, hasMinority is false.
        // We need to set new proposal to have exactly fuzz_newVotes votes. 
        // With MockVault weight per member = 1, we would need fuzz_newVotes different addresses to vote.
        // That's not feasible in a single test. So we need a way to batch votes.
        // Instead, we can modify the MockVault to return a configurable weight per member? 
        // But then we'd need to set it, which requires a setter.
        // Simpler: We'll just use the existing voteProposal function from many addresses in a loop.
        // Since loop count is limited by gas, we accept fuzz_newVotes up to some bound.

        // Actually, the simplest property that highlights the difference:
        // "After a call to cancelProposal, if the call did not revert, then mapPID_votes[oldProposalID] should be 0
        //  AND hasMinority(newProposalID) must have been true before the call."
        // But the buggy version changes the state even without minority. So we check the revert condition.

        // To set votes, we'll just use voteProposal from different addresses.
        address[] memory voters = new address[](fuzz_newVotes + 1);
        for (uint i = 0; i < fuzz_newVotes + 1; i++) {
            voters[i] = address(uint160(i + 1000));
            vm.deal(voters[i], 0);
        }
        // Set old proposal votes
        for (uint i = 0; i < fuzz_oldVotes; i++) {
            vm.prank(voters[i]);
            c.voteProposal(1);
        }
        // Set new proposal votes
        for (uint i = 0; i < fuzz_newVotes; i++) {
            vm.prank(voters[i]);
            c.voteProposal(2);
        }
        // Make old proposal finalising
        // To do that, we need quorum and majority. Quorum = totalWeight/3 = 1000/3 = 333
        // If fuzz_oldVotes > 333 and > majority, voteProposal will call _finalise.
        // But we can also directly call _finalise? No, it's internal.
        // So we ensure old proposal gets enough votes to trigger finalising when someone votes.
        // Add extra votes to old proposal to trigger finalising.
        if (fuzz_oldVotes <= 333) {
            // add votes to reach quorum and majority
            uint extra = 334 - fuzz_oldVotes;
            for (uint i = 0; i < extra; i++) {
                vm.prank(voters[fuzz_oldVotes + i]);
                c.voteProposal(1);
            }
            fuzz_oldVotes += extra;
        }
        if (c.hasMajority(1) == false) {
            // add more to ensure majority
            uint totalW = MockVault(address(c.VAULT())).totalWeight();
            uint majority = totalW / 2 + 1;
            uint current = c.mapPID_votes(1);
            uint extra = majority - current;
            for (uint i = 0; i < extra; i++) {
                vm.prank(address(uint160(2000 + i)));
                c.voteProposal(1);
            }
        }
        // Now old proposal should be finalising after the last vote.
        // The last vote that triggered finalising set mapPID_timeStart.

        // Actually, after voteProposal triggers _finalise, mapPID_finalising becomes true.
        // But we also need to set block.timestamp so that cool off period hasn't passed.
        vm.warp(0); // set timestamp to 0

        // Before calling cancelProposal, record old votes
        uint oldVotesBefore = c.mapPID_votes(1);
        bool newProposalHasMinority = c.hasMinority(2);

        // Call cancelProposal
        bool ok = true;
        try c.cancelProposal(1, 2) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert: If the call succeeded (ok == true), then newProposal must have had minority BEFORE the call.
        // In reference C, it would revert if not minority, so ok implies minority.
        // In buggy C, ok can be true even without minority, so asserting (ok == true => newProposalHasMinority == true) will fail for buggy.
        assertTrue(!ok || newProposalHasMinority, "cancelProposal succeeded without minority");
    }
}

